/* generated by build-web.mjs */
const SHELL = "tripdesk-shell-65a2d96a64e5";
const FILES = ["./", "./index.html", "./manifest.webmanifest", "./icon-192.png", "./icon-512.png"];

/* GitHub Pages serves the shell with max-age=600, and addAll goes through the
   HTTP cache like any other fetch. Without cache:"reload" a *freshly named*
   cache can be filled from a ten-minute-old copy — so the worker updates, the
   cache key changes, and the app you get is still the previous deploy. */
self.addEventListener("install", (e) => {
  const fresh = FILES.map((f) => new Request(f, { cache: "reload" }));
  e.waitUntil(caches.open(SHELL).then((c) => c.addAll(fresh)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (e) => {
  e.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== SHELL).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

/* Navigations: serve the cached shell straight away, refresh it behind you.
   The refresh revalidates against the server rather than trusting the same
   ten-minute window, or the copy it writes back is the stale one again.
   Never intercept Firebase — its SDK does its own offline handling and a
   cached auth or Firestore response would be actively harmful. */
self.addEventListener("fetch", (e) => {
  const url = new URL(e.request.url);
  if (e.request.method !== "GET") return;
  if (url.origin !== self.location.origin) return;

  if (e.request.mode === "navigate") {
    e.respondWith(
      caches.match("./index.html").then((hit) => {
        const live = fetch(e.request, { cache: "no-cache" })
          .then((res) => { caches.open(SHELL).then((c) => c.put("./index.html", res.clone())); return res; })
          .catch(() => hit);
        return hit || live;
      }),
    );
    return;
  }

  e.respondWith(caches.match(e.request).then((hit) => hit || fetch(e.request)));
});
